/**
 * One-time backfill script to ensure all existing bookings have a correct `source` value:
 * - "ONLINE": For bookings created via the public booking endpoint (/book)
 * - "ADMIN":  For bookings created from the admin dashboard (/dashboard/bookings)
 * 
 * Decision Logic:
 * 1. If booking already has `source === "ADMIN"` explicitly set, retain "ADMIN".
 * 2. If booking was created via the public booking frontend:
 *    - Has `transactionId` starting with "TEST-" (generated by BookingFlow.jsx: `TEST-${Date.now()}`)
 *    - Has `provider === "PAYHERE"` or `payherePaymentId != null`
 *    - Has `orderId` starting with "RV-" and payment method "Pay Later" with 0 initial payment
 *    -> Classified as "ONLINE".
 * 3. If booking was created via Admin Dashboard:
 *    - Payment method is staff-only ("Pay at Counter", "Bank Wire", "Cash") without public test stubs
 *    - Associated with admin user creation
 *    -> Classified as "ADMIN".
 */

const { PrismaClient } = require("@prisma/client");
const prisma = new PrismaClient();

async function backfillBookingSource() {
  console.log("=== Starting Booking Source Backfill ===");

  const bookings = await prisma.booking.findMany({
    include: {
      payment: true,
      leader: {
        select: { id: true, name: true, email: true, role: true },
      },
    },
    orderBy: { id: "asc" },
  });

  console.log(`Found ${bookings.length} total booking(s) to inspect.\n`);

  let updatedCount = 0;
  const auditReport = [];

  for (const booking of bookings) {
    const payment = booking.payment || {};
    const txnId = payment.transactionId || "";
    const method = payment.method || "";
    const provider = payment.provider || "";
    const currentSource = booking.source;

    let determinedSource = "ONLINE";
    let rationale = "";

    if (currentSource === "ADMIN" && !txnId.startsWith("TEST-")) {
      determinedSource = "ADMIN";
      rationale = "Explicitly created via Admin Dashboard with staff transaction flow";
    } else if (txnId.startsWith("TEST-")) {
      determinedSource = "ONLINE";
      rationale = `Public frontend test stub detected in transactionId (${txnId})`;
    } else if (provider === "PAYHERE" || payment.payherePaymentId) {
      determinedSource = "ONLINE";
      rationale = "Online payment provider (PayHere)";
    } else if (["Pay at Counter", "Bank Wire", "Cash"].includes(method)) {
      determinedSource = "ADMIN";
      rationale = `Staff payment method recorded (${method})`;
    } else {
      // Default fallback
      determinedSource = booking.source || "ONLINE";
      rationale = `Retained existing value (${determinedSource})`;
    }

    const needsUpdate = currentSource !== determinedSource;

    if (needsUpdate) {
      await prisma.booking.update({
        where: { id: booking.id },
        data: { source: determinedSource },
      });
      updatedCount++;
    }

    auditReport.push({
      id: booking.id,
      date: booking.bookedDate.toISOString().split("T")[0],
      currentSource,
      determinedSource,
      updated: needsUpdate ? "YES" : "NO",
      method,
      txnId,
      rationale,
    });
  }

  console.table(auditReport);
  console.log(`\n=== Backfill Completed: ${updatedCount} booking(s) updated out of ${bookings.length} ===\n`);
}

backfillBookingSource()
  .catch((err) => {
    console.error("Backfill failed:", err);
    process.exit(1);
  })
  .finally(async () => {
    await prisma.$disconnect();
  });
